// token, cloud credentials) are encrypted at rest and never returned.
type ClusterCreateRequest struct {
	AksClusterName *string `json:"aks_cluster_name,omitempty"`
	AwsAccessKeyId *string `json:"aws_access_key_id,omitempty"`
	AwsRegion      *string `json:"aws_region,omitempty"`

	// AwsRoleArn Optional role to assume after authenticating.
	AwsRoleArn          *string `json:"aws_role_arn,omitempty"`
	AwsSecretAccessKey  *string `json:"aws_secret_access_key,omitempty"`
	AwsSessionToken     *string `json:"aws_session_token,omitempty"`
	AzureClientId       *string `json:"azure_client_id,omitempty"`
	AzureClientSecret   *string `json:"azure_client_secret,omitempty"`
	AzureResourceGroup  *string `json:"azure_resource_group,omitempty"`
	AzureSubscriptionId *string `json:"azure_subscription_id,omitempty"`
	AzureTenantId       *string `json:"azure_tenant_id,omitempty"`

	// Ca PEM-encoded CA certificate bundle (token method).
	Ca *string `json:"ca,omitempty"`

	// ConnectionMethod How Spacefleet connects to the cluster.
	//   - in_cluster: Spacefleet runs in this cluster; use its service account.
	//   - kubeconfig: a supplied kubeconfig with embedded static credentials.
	//   - token: explicit API URL + CA + ServiceAccount bearer token.
	//   - eks/gke/aks: cloud-native auth (credentials minted at connect time).
	ConnectionMethod ConnectionMethod `json:"connection_method"`
	EksClusterName   *string          `json:"eks_cluster_name,omitempty"`

	// Endpoint API server URL (token method).
	Endpoint    *string `json:"endpoint,omitempty"`
	GcpLocation *string `json:"gcp_location,omitempty"`
	GcpProject  *string `json:"gcp_project,omitempty"`

	// GcpServiceAccountKey GCP service-account JSON key.
	GcpServiceAccountKey *string `json:"gcp_service_account_key,omitempty"`
	GkeClusterName       *string `json:"gke_cluster_name,omitempty"`

	// InsecureSkipTls Disable TLS verification (token method; use sparingly).
	InsecureSkipTls *bool `json:"insecure_skip_tls,omitempty"`

	// Kubeconfig Full kubeconfig YAML with embedded static credentials.
	Kubeconfig *string `json:"kubeconfig,omitempty"`
	Name       string  `json:"name"`

	// Token ServiceAccount bearer token (token method).
	Token *string `json:"token,omitempty"`
}

// ClusterIdentity The identity the cluster's stored credentials resolve to, as reported by
// the Kubernetes API (a SelfSubjectReview). On older API servers this may be
// unavailable, in which case the fields are empty.
type ClusterIdentity struct {
	Groups []string `json:"groups"`
	Uid    *string  `json:"uid,omitempty"`

	// Username The authenticated user, e.g. "system:serviceaccount:spacefleet:reader".
	Username *string `json:"username,omitempty"`
}

// ClusterRbac A generated RBAC manifest (or best-effort guidance) for selected capabilities.
type ClusterRbac struct {
	// Manifest For connection methods with an addressable in-cluster subject
	// (in_cluster, token), a ready-to-apply ClusterRole + ClusterRoleBinding
	// granting the selected capabilities' full rule set to the resolved
	// subject. For other methods (kubeconfig, eks, gke, aks), best-effort
	// guidance rather than a directly applicable manifest.
	Manifest string `json:"manifest"`
}

// ClusterRbacRequest The capabilities to grant in the generated manifest.
type ClusterRbacRequest struct {
	// Keys Capability keys to include (e.g. ["view_pods", "restart_workloads"]).
	// Each must be a known capability; the manifest grants the union of the
	// selected capabilities' full rule sets.
	Keys []string `json:"keys"`
}

